git -C "$fixture" add placeholder
GIT_AUTHOR_DATE='2000-01-01T00:00:00Z' GIT_COMMITTER_DATE='2000-01-01T00:00:00Z' git -C "$fixture" commit -qm fixture
sha="$(git -C "$fixture" rev-parse HEAD)"
